<script setup lang="ts">const {data:links}=await useFetch('/api/public/links');const groups=computed(()=>Object.groupBy(links.value||[],l=>l.group||'朋友们'))</script><template><main class="container py-16"><p class="text-xs uppercase tracking-widest" style="color:var(--accent)">Good people, good work</p><h1 class="mt-3 text-5xl font-semibold">友情链接</h1><p class="mt-4 max-w-xl" style="color:var(--muted)">感谢这些认真创造、分享与生活的朋友。</p><section v-for="(items,name) in groups" :key="name" class="mt-12"><h2 class="mb-4 text-xl font-semibold">{{name}}</h2><div class="grid gap-4 sm:grid-cols-2 lg:grid-cols-3"><a v-for="link in items" :key="link.id" :href="link.url" target="_blank" rel="noopener noreferrer" class="rounded-2xl border p-5 transition hover:-translate-y-0.5" style="border-color:var(--border);background:var(--surface)"><div class="flex items-center gap-3"><img v-if="link.logo" :src="link.logo" :alt="`${link.name} Logo`" class="h-10 w-10 rounded-lg object-cover"><span v-else class="grid h-10 w-10 place-items-center rounded-lg bg-black/5 dark:bg-white/10">✳</span><strong>{{link.name}}</strong></div><p class="mt-3 text-sm" style="color:var(--muted)">{{link.description}}</p></a></div></section></main></template>
